custom_css:
/*作者：lazyalie*/
/* 作者有话说: 禁商用二传。支持商业化的不许用我的美化。此为我早期美化的重置版，用到了许多老师的代码和类名，真的非常感谢。 */



/* ========全局控制======= */
:root {
  --模糊度: 8px;
  --饱和度:100%;
  --气泡宽度: 100%;
  --user和char气泡间距: 60px;
  --气泡和输入框间距: 150px;
  --输入框透明度: 1;/* 把这个数字改成0可以隐藏输入框 */
  --思维链文本: "⋆⁺₊⋆ ☾ ⋆⁺₊⋆";
  --输入框内文字:"人间何所以，观风与月舒"
}
/* =======全局控制结束======= */






/* 删掉这串user头像月相就会显示 */
.mes[is_user="true"] .avatar::after {
    display: none !important;
}


/*感谢咩野老师的全局阴影去除*/
body *:not(#send_form):not(#send_form *):not(.mes .avatar ):not(.mes .avatar  *){
  box-shadow: none !important;
  filter: none !important;  
}

/* ===== 顶栏 ===== */
#top-settings-holder {
    background: none !important;  
    background: rgba(0, 0, 0, 0) !important;  
    border-radius: 12px;
    box-shadow: none !important;
  filter: none !important;  
    border: 1px solid rgba(255, 255, 255, 0.1);
}
/* top-bar插件  */
#extensionTopBar {
    background: rgba(255, 255, 255, 0)  !important;
    border-radius: 15px !important;
    z-index: 9998 !important; 
    position: relative !important;
    box-shadow: none !important;
    filter: none !important;  
}
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}
#top-settings-holder .drawer {
    flex: 1;
}
#top-settings-holder .drawer-icon {
    display: block;
    margin: 0 auto;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 24px;
    height: 24px;
    opacity: 1 !important;
}

.drawer-icon.fa-fw:hover {
    transform: scale(1.2);
    transition: transform 0.2s ease-in-out;
}
#ai-config-button .drawer-icon {
   background-image: url('https://iili.io/K42fcG4.png');
}

#sys-settings-button .drawer-icon {
   background-image: url('https://iili.io/K42fkFV.png');
}
#advanced-formatting-button .drawer-icon {
   background-image: url('https://iili.io/K42fvcB.png');
}
#WI-SP-button .drawer-icon{
   background-image: url('https://iili.io/K42f4ta.png');
}
#user-settings-button .drawer-icon {
   background-image: url('https://iili.io/K42fiMv.png');
}
#backgrounds-button .drawer-icon{
   background-image: url('https://iili.io/K42f88P.png');
}
#extensions-settings-button .drawer-icon {
   background-image: url('https://iili.io/K42fO6Q.png');
}
#table_database_settings_drawer .drawer-icon {
   background-image: url('https://iili.io/K42fl6l.png');
}
#persona-management-button .drawer-icon {
   background-image: url('https://iili.io/K42fl6l.png');
}
#rightNavHolder .drawer-icon {
   background-image: url('https://iili.io/K42fG87.png');
}

#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: url('https://iili.io/K42fV99.png') !important;
    transform: scale(1.1);
    transition: all 0.3s ease-in-out;
}

/* ===== 底栏 ===== */
#send_form [class*="fa-"]::before {
    content: '' !important;
    display: inline-block;
    width: 20px;
    height: 20px;
    background-image: url('https://iili.io/K42fV99.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
    transition: all 0.3s ease-in-out;
}
#mes_stop i::before {
    background-image: url('https://iili.io/K42fiMv.png') !important;
}
/*感谢royoyo老师分享的二改NA师的悬浮底栏*/
#send_form {
    background: none !important;  
    background: rgba(0, 0, 0, 0) !important;
    backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    border: 1.5px solid  rgba(255, 255, 255, 0.2);
    width: 98%;
    display: flex !important;
    align-items: center !important;
    border-radius: 40px !important; 
    padding: 8px 15px !important; 
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
    transition: all 0.3s ease; 
    opacity: var(--输入框透明度);
}

/* 鼠标悬停 */
#send_form:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
    opacity: 1;
}

/* 激活后*/
#send_form:focus-within { 
    opacity: 1; 
    box-shadow: 0 6px 25px rgba(0, 0, 0, 0.4);   
    transform: translateY(-2px); 
    border: 1.5px solid rgba(255, 255, 255, 0.6);    
}
#send_textarea {
    flex-grow: 1 !important;
    min-height: 24px !important; 
    line-height: 1.5; 
    clip-path: none; 
    background-color: transparent;
    border-color: transparent;
    border-radius: 16px !important;
}

/* 确保输入框固定在底部 */
#form_sheld {
    position: sticky;
    bottom: 70px;
    transition: transform 0.3s ease;
}

/* 鼠标悬浮在整个底部区域时，向上平移 */
#form_sheld:hover {
    transform: translateY(-5px);
}
#sheld, 
#chat {
    height: calc(100dvh + var(--bottomFormBlockSize));
    max-height: calc(100dvh + var(--bottomFormBlockSize));
}


#qr--bar button{  
   background-color: none;
  box-shadow: none !important;
  bottom: 5px;
  margin: 2px 2px !important;
}

/* 感谢12老师分享的隐藏QR */
#send_form:hover #qr--bar {
    height: 20px;
    transition: all 0.5s ease;
}
#qr--bar {
    height: 0.1px;
}

/* 底栏呼吸灯效果 */
#send_form {
    position: relative;
    transition: all 0.5s ease-in-out;
}

#send_form:hover {
    box-shadow: 
        0 0 5px rgba(255, 255, 255, 0.6),
        0 0 10px rgba(255, 255, 255, 0.4),
        0 0 15px rgba(255, 255, 255, 0.2);
    animation: breathe 5s ease-in-out infinite;
}

/* 呼吸灯动画 */
@keyframes breathe {
    0% {
        box-shadow: 
            0 0 5px rgba(255, 255, 255, 0.6),
            0 0 10px rgba(255, 255, 255, 0.4),
            0 0 15px rgba(255, 255, 255, 0.2);
    }
    50% {
        box-shadow: 
            0 0 10px rgba(255, 255, 255, 0.8),
            0 0 20px rgba(255, 255, 255, 0.6),
            0 0 30px rgba(255, 255, 255, 0.4);
    }
    100% {
        box-shadow: 
            0 0 5px rgba(255, 255, 255, 0.6),
            0 0 10px rgba(255, 255, 255, 0.4),
            0 0 15px rgba(255, 255, 255, 0.2);
    }
}

/* 感谢墨千尾老师的输入框内文字自定义 */
#nonQRFormItems {
  position: relative;
}

#send_textarea::placeholder {
  color: rgba(0, 0, 0, 0) !important;
  text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--输入框内文字);
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  font-style: normal;
  font-size: 0.5em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}
/* 感谢nini老师分享的隐藏输入框右下角的缩放手柄（小黑点） */
#send_textarea {
    resize: none !important;
}

/* ===对话部分===*/
#chat .mes:last-of-type {
    margin-bottom: var(--气泡和输入框间距) !important; 
}
.mes:not(:last-child) {
    margin-bottom: var(--user和char气泡间距) !important; 
}

.mes {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    background: none !important;
}
.mes .mesAvatarWrapper {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    position: relative !important;
    z-index: 10 !important;
}
.mes .avatar {
    margin-bottom: 8px !important; 
    z-index: 2 !important;
    position: relative !important; 
    border: none !important;
    outline: none !important;
}
.mes .avatar::after { 
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -48.2%) !important; 
    width: 520px !important; 
    height: 520px !important;
    background-image: url('https://iili.io/K42fPoJ.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    z-index: -1 !important; 
    pointer-events: none !important;
}

.mes[is_user="true"] .avatar img {
    box-shadow: 
        0 0 10px rgba(255, 255, 255, 0.8),
        0 0 20px rgba(255, 255, 255, 0.6),
        0 0 30px rgba(255, 255, 255, 0.4) !important;
    filter: brightness(1.1) !important;
    border: none !important;
    outline: none !important;
}
.mes .avatar img {
    border-radius: 50% !important;
    z-index: 2 !important;
    position: relative !important;
}
.mesAvatarWrapper > .flex-container {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    gap: 2px !important; 
    margin-top: 5px !important;
    margin-bottom: 5px !important; 
    z-index: 2 !important;
    position: relative !important;
}

/* 信息文字样式 */
.mesAvatarWrapper .mes_timer,
.mesAvatarWrapper .mesIDDisplay,
.mesAvatarWrapper .tokenCounterDisplay,
.mesAvatarWrapper .name_text {
    font-size: 0.7em !important;
    text-align: center !important;
    color: var(--main-text-color) !important;
}

/* 气泡主体样式 */
.mes .mes_block {
    background: var(--SmartThemeBotMesBlurTintColor);
    backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    border-radius: 20px !important; 
    width: var(--气泡宽度) !important;
    max-width: none !important; 
    padding: 15px !important;
    position: relative !important;
    margin-top: 0 !important; 
}
.mes[is_user='true'] .mes_block,
.mes_block[is_user='true'] {
  background:var(--SmartThemeUserMesBlurTintColor) ;
  }
.mes .mes_text {
    width: 100% !important;
    padding: 0 !important;
}


.mes .mes_reasoning {
    margin-top: 10px !important;
    width: 100% !important;
}

/* 文本美化 */
/*感谢墨千尾老师的发光文本美化*/
q {
    color: rgba(255, 255, 255, 1); 
    font-style: normal;
    font-size: 1.2em; 
    text-shadow: 
        0 0 5px rgba(255, 255, 255, 0.8),
        0 0 10px rgba(255, 255, 255, 0.6),
        0 0 15px rgba(255, 255, 255, 0.4);
}
em {
    text-decoration: underline;
    text-decoration-style: dashed;
    text-decoration-color: rgba(255, 255, 255, 0.8);
    text-shadow: 0 0 3px rgba(255, 255, 255, 0.5);
    text-decoration-thickness: 1px;
    text-underline-offset: 2px;
}
code {
    background: rgba(255, 255, 255, 0) !important;
    color: var(--main-text-color); /* 使用CSS变量 */
    backdrop-filter: blur(8px) !important;
    border-radius: 4px !important;
    padding: 2px 6px !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1) !important;
}
pre code {
    color: var(--main-text-color) !important;
    background: rgba(255, 255, 255, 0) !important;
    border-radius: 8px !important;
    padding: 16px !important;
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1) !important;
    display: block !important;
    overflow-x: auto !important;
}
/*感谢nakari老师分享的最后一条消息与下方区域距离保持一致代码*/
/* 通用CSS */
.mes .mes_timer:empty,
.mes .mesIDDisplay:empty,
.mes .tokenCounterDisplay:empty {
    display: none;
}
.last_mes .mesAvatarWrapper {
    padding-bottom: 0px; 
}

/* === 思维链 === */
.mes_reasoning_summary {
    list-style: none;
    cursor: pointer;
    display: flex !important;
    align-items: center;
    justify-content: center; /* 居中 */
}

.mes_reasoning_header {
    background: rgba(255, 255, 255, 0); 

    border-radius: 12px;
    padding: 10px 20px;
    border: none !important;
    transition: transform 0.3s ease; 
    text-align: center;
    margin: auto; 
}
.mes_reasoning_summary:hover .mes_reasoning_header {
    transform: scale(1.05);
}

.mes_reasoning_header_title {
    font-size: 0 !important;
}

.mes_reasoning_header_title::before {
    content: var(--思维链文本);
    font-size: 10px;
    color: var(--sub-text-color) !important;;
    font-weight: 60;
    letter-spacing: 1px;
}

.mes_reasoning_arrow {
    font-size: 0 !important;
}

.mes_reasoning {
    margin: 8px auto 0;
    padding: 16px;
    background: rgba(255, 255, 255, 0); 

    border-radius: 8px;
    color: ver(--SmartThemeBodyColor );
    font-family: monospace;
    font-size: 9px;
    line-height: 1.5;
    text-align: left;
    max-width: 90%;
    border: 1px solid rgba(255, 255, 255, 0); 
}

/*===七七八八框框===*/
#user-settings-block h4,
.standoutHeader,
.inline-drawer-header{
    background-image :none!important;
    border-radius: 35px !important;
    padding:10px;   
    box-shadow: 2px 3px 3px  rgba(0, 0, 0, 0.1) !important;
   min-height: 40px !important;    
}
input[type="number"],
textarea:not(#send_textarea,.height100p.wide100p.maximized_textarea.monospace,.height100p.wide100p.maximized_textarea.mdHotkeys),
.text_pole,
select{
background: none;
shadow: none !important;
filter: none !important;   
}   
div.inline-drawer-content  {
    background-color: rgba(255, 255, 255, 0) !important;
    border-radius: 10px !important;  
   margin-top: 2px;
   padding: 8px;
}
.height100p.wide100p.maximized_textarea.monospace,
textarea.height100p.wide100p.maximized_textarea.mdHotkeys{
background-color:rgba(255, 242, 248, 0) !important ;
backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    border: none;

}  
/*===滚动条和滑动条===*/
/* 隐藏所有滚动条 */
::-webkit-scrollbar {
  display: none !important;
}
/* Firefox */
* {
  scrollbar-width: none !important;
}
input[type="range"]::-webkit-slider-runnable-track {
  width: 100%;
  height: 2px;
  background: var(--SmartThemeBodyColor);
  border-radius: 2px;
  box-shadow: none !important;
}
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  background: rgba(0, 0, 0, 0) !important;
  cursor: pointer;
  box-shadow: none !important;
}
input[type="range"]::-webkit-slider-thumb {
  margin-top: -7px;
  box-shadow: none !important;
}
/*====正则====*/
/*感谢墨千尾老师分享的正则留空*/
#saved_regex_scripts {
  padding-right: 50px; 
}
#saved_scoped_scripts {
padding-right: 50px; 
}
/*感谢camellia老师分享的正则全部显示*/
.regex_script_name.overflow-hidden {
  white-space: normal;
}
/* ====收藏角色==== */
.character_select.is_fav .avatar {
    outline: none !important;
    box-shadow: 
        0 0 8px rgba(255, 255, 255, 0.8),
        0 0 16px rgba(255, 255, 255, 0.6),
        0 0 24px rgba(255, 255, 255, 0.4);
}
.character_select.is_fav .ch_name {
    color: rgba(255, 255, 255, 0.9) !important;
    text-shadow: 
        0 0 8px rgba(255, 255, 255, 0.8),
        0 0 12px rgba(255, 255, 255, 0.6),
        0 0 16px rgba(255, 255, 255, 0.4);
}
/* 感谢12老师分享的收藏区左右滑动 */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  height: calc(var(--avatar-base-height) + 10px);
}
body.big-avatars #HotSwapWrapper > div {
  height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
#HotSwapWrapper > div::-webkit-scrollbar {
  height: 5px; 
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--ui-color-sec); 
  border-radius: 5px; 
}
/* ===弹窗部分=== */
/*感谢后藤老师为我提供的消息弹窗代码，我修改后也一并放上来了*/
#toast-container > .toast {
    color:var(--main-text-color)!important;
    background: rgba(255, 255, 255, 0) !important;
    backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    border-radius: 16px !important;
    padding-left: 55px;
    margin: 8px 0;
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.2);
    overflow: hidden;
    display: block;
}

/* 弹窗状态图标 */
#toast-container > .toast::before {
    content: '' !important;
    font-family: "Font Awesome 6 Free", "Segoe UI Symbol", sans-serif !important;
    font-weight: 900 !important;
    position: absolute !important;
    left: 15px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    font-size: 16px !important;
    color: var(--main-text-color) !important;
}
#toast-container > .toast-success::before { content: "\f00c" !important; } /* 对勾 */
#toast-container > .toast-error::before   { content: "\f00d" !important; } /* 叉号 */
#toast-container > .toast-info::before    { content: "\f129" !important; } /* i */
#toast-container > .toast-warning::before { content: "\f12a" !important; } /* ! */
.toast-title {
    display: inline !important;
    font-size: 14px !important;
    font-weight: 700 !important;
    margin-right: 8px !important;
    color: #444 !important;
}
　
/* 设置，菜单区域 */
div#options.font-family-reset,
div#extensionsMenu.options-content {
    backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) saturate(var(--饱和度)) !important; 
    border-radius: 12px !important;
    border: 1px solid rgba(255, 255, 255, 0) !important;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1) !important;
    padding: 12px !important;    
}




